1	// `roster status`: where a run is — its last completed step, any step still in progress, the steps that failed,
2	// and the spend against the budget (DESIGN.md §"CLI", §"Data model"). The command reads the append-only `events`
3	// log that `roster run` writes into .roster/roster.db; renderStatus is pure over the same step log.
4	import { Database } from "bun:sqlite";
5	import { existsSync } from "node:fs";
6	import { DEFAULT_DB } from "../agent/coordinator.ts";
7	import type { Command } from "../cli.ts";
8	import { UsageError } from "./review.ts";
9	
10	const USAGE = `usage: roster status [--db <path>] [--budget <usd>]
11	
12	  --db <path>      the state database holding the run's step log (default ${DEFAULT_DB})
13	  --budget <usd>   what to compare the spend against; default: the budget recorded for the latest run
14	
15	One line per step kind: the coordinator's tool calls are the steps, plus one "llm" step per model turn, which
16	carries that turn's cost. Everything the run reported is shown; nothing is inferred beyond the log.`;
17	
18	/** One entry of a run's step log, oldest first. */
19	export interface StatusEvent {
20	  runId: string;
21	  step: string;
22	  status: "started" | "done" | "failed";
23	  /** ISO 8601. */
24	  at: string;
25	  /** This step's cost in USD, when it has one. */
26	  costUsd?: number;
27	}
28	
29	/** The run of the last event in the log: the greatest `at`, ties and unparseable dates broken by log order. */
30	function latestRunId(events: readonly StatusEvent[]): string {
31	  let runId = events[events.length - 1]!.runId;
32	  let best = Number.NEGATIVE_INFINITY;
33	  for (const e of events) {
34	    const t = Date.parse(e.at);
35	    if (Number.isNaN(t)) continue;
36	    if (t >= best) {
37	      best = t;
38	      runId = e.runId;
39	    }
40	  }
41	  return runId;
42	}
43	
44	function usd(amount: number): string {
45	  return `$${amount.toFixed(2)}`;
46	}
47	
48	/**
49	 * Where the latest run is: its last completed step, the steps that started and never finished ("in progress"),
50	 * the steps whose last word was a failure, and the cost against the budget as "$x.xx of $y.yy".
51	 */
52	export function renderStatus(events: readonly StatusEvent[], budgetUsd: number): string {
53	  if (events.length === 0) return "no runs yet";
54	  const runId = latestRunId(events);
55	  const run = events.filter((e) => e.runId === runId);
56	
57	  // What each step last said about itself: a step that started and never finished is still running, and a step
58	  // that failed and was not retried is a failure. A step that failed and then completed is neither.
59	  const last = new Map<string, StatusEvent["status"]>();
60	  for (const e of run) last.set(e.step, e.status);
61	
62	  // The last step that finished and stayed finished: a step whose last word was a failure is not one.
63	  const lastDone = run.filter((e) => e.status === "done" && last.get(e.step) === "done").at(-1);
64	  const inProgress = [...last].filter(([, s]) => s === "started").map(([step]) => step);
65	  const failed = [...last].filter(([, s]) => s === "failed").map(([step]) => step);
66	  const spent = run.reduce((sum, e) => sum + (e.costUsd === undefined || !Number.isFinite(e.costUsd) ? 0 : e.costUsd), 0);
67	
68	  const lines = [`run ${runId}`];
69	  if (lastDone) lines.push(`last completed step: ${lastDone.step}`);
70	  if (inProgress.length > 0) lines.push(`in progress: ${inProgress.join(", ")}`);
71	  if (failed.length > 0) lines.push(`failed steps: ${failed.join(", ")}`);
72	  lines.push(`cost: ${usd(spent)} of ${usd(Number.isFinite(budgetUsd) ? budgetUsd : 0)}`);
73	  return lines.join("\n");
74	}
75	
76	interface EventRow {
77	  run_id: string;
78	  kind: string;
79	  payload: string;
80	  created_at: string;
81	}
82	
83	/** The step a logged event is, or null for the events that are not steps (an unknown kind, the run's start). */
84	function stepOf(kind: string, payload: Record<string, unknown>): Pick<StatusEvent, "step" | "status" | "costUsd"> | null {
85	  switch (kind) {
86	    case "tool": {
87	      const name = typeof payload.name === "string" && payload.name.length > 0 ? payload.name : "tool";
88	      return { step: name, status: payload.ok === false ? "failed" : "done", costUsd: undefined };
89	    }
90	    case "llm": {
91	      const cost = typeof payload.costUsd === "number" ? payload.costUsd : undefined;
92	      return { step: "llm", status: "done", costUsd: cost };
93	    }
94	    // A note is either the run's own error (the LLM call that failed) or something the tools asked to surface.
95	    case "note":
96	      return payload.llm_error === undefined
97	        ? { step: "note", status: "done", costUsd: undefined }
98	        : { step: "llm", status: "failed", costUsd: undefined };
99	    case "end":
100	      return { step: "end", status: "done", costUsd: undefined };
101	    default:
102	      return null;
103	  }
104	}
105	
106	export interface StatusLog {
107	  events: StatusEvent[];
108	  /** The budget the latest run was started with, when the log records one. */
109	  budgetUsd: number | undefined;
110	}
111	
112	function parse(payload: string): Record<string, unknown> {
113	  try {
114	    const v: unknown = JSON.parse(payload);
115	    return typeof v === "object" && v !== null ? (v as Record<string, unknown>) : {};
116	  } catch {
117	    return {};
118	  }
119	}
120	
121	/**
122	 * Reads every run's step log from the state database, oldest first. A database that is missing, unreadable or
123	 * not a roster state database reads as no events rather than as an error.
124	 */
125	export function readStatusLog(dbPath: string): StatusLog {
126	  const empty: StatusLog = { events: [], budgetUsd: undefined };
127	  if (!existsSync(dbPath)) return empty;
128	  let db: Database | undefined;
129	  try {
130	    db = new Database(dbPath, { readonly: true });
131	    const rows = db
132	      .query<EventRow, []>("SELECT run_id, kind, payload, created_at FROM events ORDER BY id")
133	      .all();
134	    const events: StatusEvent[] = [];
135	    let budgetUsd: number | undefined;
136	    let budgetRun: string | undefined;
137	    for (const row of rows) {
138	      const payload = parse(row.payload);
139	      if (row.kind === "start") {
140	        const config = payload.config;
141	        const budget = typeof config === "object" && config !== null ? (config as Record<string, unknown>).budgetUsd : undefined;
142	        if (typeof budget === "number" && Number.isFinite(budget)) {
143	          budgetUsd = budget;
144	          budgetRun = row.run_id;
145	        }
146	        continue;
147	      }
148	      const step = stepOf(row.kind, payload);
149	      if (!step) continue;
150	      const event: StatusEvent = { runId: row.run_id, step: step.step, status: step.status, at: row.created_at };
151	      if (step.costUsd !== undefined) event.costUsd = step.costUsd;
152	      events.push(event);
153	    }
154	    // Only the latest run's recorded budget is the one status compares against.
155	    const latest = events.length > 0 ? latestRunId(events) : undefined;
156	    return { events, budgetUsd: budgetRun !== undefined && budgetRun === latest ? budgetUsd : undefined };
157	  } catch {
158	    return empty;
159	  } finally {
160	    db?.close();
161	  }
162	}
163	
164	export interface StatusArgs {
165	  db: string;
166	  budgetUsd: number | undefined;
167	}
168	
169	/** Parses the arguments after `status`. Throws UsageError on anything it does not accept. */
170	export function parseStatusArgs(args: string[]): StatusArgs {
171	  let db = DEFAULT_DB;
172	  let budget: string | undefined;
173	  for (let i = 0; i < args.length; i++) {
174	    const a = args[i]!;
175	    const eq = a.indexOf("=");
176	    const name = eq === -1 ? a : a.slice(0, eq);
177	    const takeValue = (): string => {
178	      if (eq !== -1) return a.slice(eq + 1);
179	      const v = args[++i];
180	      if (v === undefined || v.startsWith("--")) throw new UsageError(`${name} needs a value`);
181	      return v;
182	    };
183	    if (name === "--db") db = takeValue();
184	    else if (name === "--budget") budget = takeValue();
185	    else throw new UsageError(`unexpected argument ${a}`);
186	  }
187	  if (budget === undefined) return { db, budgetUsd: undefined };
188	  const budgetUsd = Number(budget);
189	  if (!Number.isFinite(budgetUsd) || budgetUsd < 0) throw new UsageError(`--budget must be a non-negative number, got ${budget}`);
190	  return { db, budgetUsd };
191	}
192	
193	export const statusCommand: Command = {
194	  name: "status",
195	  summary: "show where the latest run is: last step, failures, cost vs budget",
196	  usage: USAGE,
197	  async run(args) {
198	    let parsed: StatusArgs;
199	    try {
200	      parsed = parseStatusArgs(args);
201	    } catch (err) {
202	      if (!(err instanceof UsageError)) throw err;
203	      console.error(`roster status: ${err.message}\n\n${USAGE}`);
204	      return 2;
205	    }
206	    const log = readStatusLog(parsed.db);
207	    if (log.events.length === 0) {
208	      console.log("no runs yet");
209	      return 0;
210	    }
211	    console.log(renderStatus(log.events, parsed.budgetUsd ?? log.budgetUsd ?? 0));
212	    return 0;
213	  },
214	};
215	
216	if (import.meta.main) {
217	  process.exitCode = await statusCommand.run(process.argv.slice(2));
218	}
