18	/** Runs one command in the repo directory. Injected by tests; the default spawns a real process. */
19	export type Runner = (cmd: string[]) => Promise<RunResult>;
20	
21	export interface OpenPrOptions {
22	  repoPath: string;
23	  branch: string;
24	  title: string;
25	  body: string;
26	  /** Build the command but never run gh. The owner/repo lookup still runs, because the opt-in check needs it. */
27	  dryRun?: boolean;
28	  /** Opt-in gate, called once with the origin remote's "owner/name". */
29	  allowRepo: (ownerRepo: string) => boolean;
