33	export interface OpenPrResult {
34	  opened: boolean;
35	  /** Only set when gh exited 0 and printed a URL. */
36	  url?: string;
37	  /** The `gh pr create` argv, whether or not it ran. Empty when there was nothing to attempt. */
38	  command: string[];
39	  reason?: string;
40	}
