68	/**
69	 * The `gh pr create` argv for one request. The body is passed as the `--body-file` argument: the frozen F03
70	 * acceptance test pins this exact argv, so it is what runs (github's `--body-file` takes a path — noted in the
71	 * task summary, not silently changed here).
72	 */
73	export function prCreateCommand(o: { branch: string; title: string; body: string }): string[] {
74	  return ["gh", "pr", "create", "--head", o.branch, "--title", o.title, "--body-file", o.body];
75	}
76	
77	/** The pull request URL in gh's stdout: the last URL token, so a leading "Warning:"/progress line is ignored. */
78	export function parsePrUrl(stdout: string): string | null {
79	  const found = stdout.match(/https?:\/\/[^\s<>"]+/g);
80	  const last = found?.at(-1);
81	  return last === undefined ? null : last.replace(/[.,;:)\]]+$/, "");
82	}
83	
84	/**
85	 * Opens a PR for `branch` on `repoPath`'s origin, if that repo allows it. Reads "owner/name" from
86	 * `git remote get-url origin` (https, ssh:// and scp-style forms) and asks `allowRepo` first; a repo that is not
87	 * opted in never reaches gh. With `dryRun` the gh command is returned unrun.
88	 */
89	export async function openPr(opts: OpenPrOptions): Promise<OpenPrResult> {
90	  const run = opts.run ?? spawnRunner(opts.repoPath);
91	
92	  let remote: RunResult;
93	  try {
94	    remote = await run(["git", "remote", "get-url", "origin"]);
95	  } catch (err) {
96	    return { opened: false, command: [], reason: `could not read the origin remote: ${message(err)}` };
97	  }
98	  if (remote.code !== 0) {
99	    return {
100	      opened: false,
101	      command: [],
102	      reason: remote.stderr.trim() || `git remote get-url origin exited ${remote.code}`,
103	    };
104	  }
105	  const ownerRepo = parseRemote(remote.stdout);
106	  if (ownerRepo === null) {
107	    return { opened: false, command: [], reason: `origin has no owner/name: ${remote.stdout.trim()}` };
108	  }
109	
110	  if (!opts.allowRepo(ownerRepo)) return { opened: false, command: [], reason: NOT_OPTED_IN };
111	
112	  const command = prCreateCommand(opts);
113	  if (opts.dryRun) return { opened: false, command, reason: DRY_RUN };
114	
115	  let gh: RunResult;
116	  try {
117	    gh = await run(command);
118	  } catch (err) {
119	    return { opened: false, command, reason: message(err) };
120	  }
121	  if (gh.code !== 0) {
122	    return { opened: false, command, reason: gh.stderr.trim() || `gh pr create exited ${gh.code}` };
123	  }
124	
125	  const url = parsePrUrl(gh.stdout);
126	  return url === null ? { opened: true, command } : { opened: true, url, command };
127	}
