// `roster act`: turns the last gate decision into a branch carrying the promoted setup, and optionally a PR
// (DESIGN.md §"Act"). Only a "promote" verdict acts; every other verdict is "nothing to act on".

export interface ActDeps {
  readJson(p: string): Promise<unknown>;
  writeFile(p: string, s: string): Promise<void>;
  git(args: string[]): Promise<{ code: number; stdout: string }>;
  openPr(o: unknown): Promise<{ opened: boolean; url?: string; reason?: string }>;
  stdout(s: string): void;
}

const USAGE = "usage: roster act --gate <gate.json> [--pr] [--dry-run]";
/** Setup ids become file names and a branch name, so they stay to a safe alphabet. */
const SAFE_ID = /^[A-Za-z0-9][A-Za-z0-9._-]*$/;

function isObject(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

/**
 * Runs `act`. The gate file holds the decision (`verdict`, or `decision`), the promoted `candidate` id, its `setup`
 * object (read from setups/candidates/<id>.json when absent) and the candidate's rules text as `rules` with its
 * destination `rules_path`. Returns 0 on success or nothing to do, 1 when a step fails, 2 on bad usage.
 */
export async function runActCommand(args: string[], deps: ActDeps): Promise<number> {
  let gatePath: string | undefined;
  let pr = false;
  let dryRun = false;
  for (let i = 0; i < args.length; i++) {
    const a = args[i]!;
    if (a === "--gate") gatePath = args[++i];
    else if (a.startsWith("--gate=")) gatePath = a.slice("--gate=".length);
    else if (a === "--pr") pr = true;
    else if (a === "--dry-run") dryRun = true;
    else {
      deps.stdout(`roster act: unexpected argument ${a}\n${USAGE}`);
      return 2;
    }
  }
  if (gatePath === undefined || gatePath === "" || gatePath.startsWith("--")) {
    deps.stdout(`roster act: --gate needs a value\n${USAGE}`);
    return 2;
  }

  let gate: unknown;
  try {
    gate = await deps.readJson(gatePath);
  } catch (err) {
    deps.stdout(`roster act: cannot read ${gatePath}: ${err instanceof Error ? err.message : String(err)}`);
    return 1;
  }
  if (!isObject(gate)) {
    deps.stdout(`roster act: ${gatePath} is not a gate decision`);
    return 1;
  }

  const verdict = gate.verdict ?? gate.decision;
  if (verdict !== "promote") {
    deps.stdout("nothing to act on");
    return 0;
  }

  const id = gate.candidate;
  if (typeof id !== "string" || !SAFE_ID.test(id)) {
    deps.stdout("roster act: the promote decision has no usable candidate id");
    return 1;
  }

  let setup: unknown = gate.setup;
  if (setup === undefined) {
    try {
      setup = await deps.readJson(`setups/candidates/${id}.json`);
    } catch (err) {
      deps.stdout(`roster act: cannot read setups/candidates/${id}.json: ${err instanceof Error ? err.message : String(err)}`);
      return 1;
    }
  }

  const branch = `roster/promote-${id}`;
  const files: string[] = [`setups/${id}.json`];
  const rules = typeof gate.rules === "string" ? gate.rules : undefined;
  const rulesPath =
    typeof gate.rules_path === "string" && gate.rules_path !== ""
      ? gate.rules_path
      : isObject(setup) && typeof setup.rules === "string"
        ? setup.rules
        : undefined;
  if (rules !== undefined && rulesPath !== undefined) {
    // The rules file lands inside the repo only.
    if (rulesPath.startsWith("/") || rulesPath.split(/[\\/]/).includes("..")) {
      deps.stdout(`roster act: refusing rules path ${rulesPath}`);
      return 1;
    }
    files.push(rulesPath);
  }

  const step = async (label: string, gitArgs: string[]): Promise<boolean> => {
    const r = await deps.git(gitArgs);
    if (r.code !== 0) deps.stdout(`roster act: git ${label} failed (exit ${r.code})`);
    return r.code === 0;
  };

  if (!(await step("checkout", ["checkout", "-b", branch]))) return 1;
  try {
    await deps.writeFile(files[0]!, `${JSON.stringify(setup, null, 2)}\n`);
    if (files.length > 1) await deps.writeFile(rulesPath!, rules!);
  } catch (err) {
    deps.stdout(`roster act: cannot write files: ${err instanceof Error ? err.message : String(err)}`);
    return 1;
  }
  if (!(await step("add", ["add", ...files]))) return 1;
  if (!(await step("commit", ["commit", "-m", `roster: promote setup ${id}`]))) return 1;
  deps.stdout(`committed ${files.join(", ")} on ${branch}`);

  if (pr) {
    const reasons = Array.isArray(gate.reasons) ? gate.reasons.filter((r): r is string => typeof r === "string") : [];
    const body = [`Promotes setup ${id}.`, ...reasons.map((r) => `- ${r}`)].join("\n");
    const res = await deps.openPr({ branch, title: `roster: promote setup ${id}`, body, dryRun });
    if (res.opened) deps.stdout(`opened ${res.url ?? "a pull request"}`);
    else deps.stdout(`no PR opened${res.reason ? `: ${res.reason}` : ""}`);
  }
  return 0;
}

import { describe, expect, test } from "bun:test";
import { runActCommand, type ActDeps } from "../src/cli/act.ts";

function make(gate: unknown, failGit?: string) {
  const out: string[] = [];
  const written: Record<string, string> = {};
  const gitCalls: string[][] = [];
  const prCalls: unknown[] = [];
  const deps: ActDeps = {
    readJson: async (p) => {
      if (p === "gate.json") return gate;
      if (p === "setups/candidates/E.json") return { id: "E", model: "m", rules: "setups/rules/default.md" };
      throw new Error("ENOENT");
    },
    writeFile: async (p, s) => void (written[p] = s),
    git: async (a) => {
      gitCalls.push(a);
      return { code: a[0] === failGit ? 1 : 0, stdout: "" };
    },
    openPr: async (o) => {
      prCalls.push(o);
      return { opened: false, reason: "dry run" };
    },
    stdout: (s) => void out.push(s),
  };
  return { deps, out, written, gitCalls, prCalls };
}

const promote = { verdict: "promote", candidate: "E", reasons: ["no regressions"], rules: "# rules\n", rules_path: "setups/rules/E.md" };

describe("roster act", () => {
  test("a non-promote decision is nothing to act on", async () => {
    const t = make({ verdict: "reject", candidate: "E" });
    expect(await runActCommand(["--gate", "gate.json", "--pr"], t.deps)).toBe(0);
    expect(t.out).toEqual(["nothing to act on"]);
    expect(t.gitCalls).toEqual([]);
    expect(t.prCalls).toEqual([]);
  });

  test("promote writes files to a new branch and commits", async () => {
    const t = make(promote);
    expect(await runActCommand(["--gate", "gate.json"], t.deps)).toBe(0);
    expect(t.gitCalls[0]).toEqual(["checkout", "-b", "roster/promote-E"]);
    expect(Object.keys(t.written).sort()).toEqual(["setups/E.json", "setups/rules/E.md"]);
    expect(t.gitCalls.at(-1)).toEqual(["commit", "-m", "roster: promote setup E"]);
    expect(t.prCalls).toEqual([]);
  });

  test("--pr calls openPr and passes dry-run through", async () => {
    const t = make(promote);
    expect(await runActCommand(["--gate", "gate.json", "--pr", "--dry-run"], t.deps)).toBe(0);
    expect(t.prCalls).toHaveLength(1);
    expect((t.prCalls[0] as { dryRun: boolean; branch: string }).dryRun).toBe(true);
    expect((t.prCalls[0] as { branch: string }).branch).toBe("roster/promote-E");
  });

  test("falls back to the candidate setup file when the gate has none", async () => {
    const t = make({ verdict: "promote", candidate: "E" });
    expect(await runActCommand(["--gate", "gate.json"], t.deps)).toBe(0);
    expect(JSON.parse(t.written["setups/E.json"]!).id).toBe("E");
  });

  test("a failing git step returns 1", async () => {
    for (const step of ["checkout", "add", "commit"]) {
      const t = make(promote, step);
      expect(await runActCommand(["--gate", "gate.json", "--pr"], t.deps)).toBe(1);
      expect(t.prCalls).toEqual([]);
    }
  });

  test("rejects unsafe ids and rules paths, and missing --gate", async () => {
    const bad = make({ verdict: "promote", candidate: "../x" });
    expect(await runActCommand(["--gate", "gate.json"], bad.deps)).toBe(1);
    expect(bad.gitCalls).toEqual([]);
    const esc = make({ ...promote, rules_path: "../evil.md" });
    expect(await runActCommand(["--gate", "gate.json"], esc.deps)).toBe(1);
    expect(esc.gitCalls).toEqual([]);
    expect(await runActCommand([], make(promote).deps)).toBe(2);
  });
});
